public record GoldenExemplar(string InputQuery, string VerifiedOutput);

public class DynamicFewShotService
{
    private readonly IChatClient _chatClient;
    private readonly IExemplarVectorStore _vectorStore;

    public DynamicFewShotService(IChatClient chatClient, IExemplarVectorStore vectorStore)
    {
        _chatClient = chatClient;
        _vectorStore = vectorStore;
    }

    public async Task<string> GenerateSqlQueryAsync(string naturalLanguageQuestion, CancellationToken ct = default)
    {
        // 1. Retrieve 3 most similar past SQL generation examples
        List<GoldenExemplar> similarExemplars = await _vectorStore.FindSimilarExemplarsAsync(
            naturalLanguageQuestion,
            topK: 3,
            ct);

        // 2. Assemble exemplars into structured demonstration block
        var promptBuilder = new StringBuilder();
        promptBuilder.AppendLine("Translate natural language questions into valid T-SQL for SQL Server 2022.");
        promptBuilder.AppendLine("Study the examples below:");
        promptBuilder.AppendLine();

        foreach (var ex in similarExemplars)
        {
            promptBuilder.AppendLine($"Question: {ex.InputQuery}");
            promptBuilder.AppendLine($"SQL: {ex.VerifiedOutput}");
            promptBuilder.AppendLine("---");
        }

        promptBuilder.AppendLine($"Question: {naturalLanguageQuestion}");
        promptBuilder.AppendLine("SQL:");

        var response = await _chatClient.CompleteAsync(promptBuilder.ToString(), cancellationToken: ct);
        return response.Message.Text?.Trim() ?? string.Empty;
    }
}
